var RTL_LANGS = ["ar"];

function setLang(code){
  if(!I18N[code]) code = "en";
  try{ localStorage.setItem("ac_lang", code); }catch(e){}
  applyLang(code);
}

function applyLang(code){
  var base = I18N.en;
  var over = I18N[code] || {};
  var dict = {};
  for(var k in base) dict[k] = (over[k] !== undefined) ? over[k] : base[k];
  document.documentElement.setAttribute("dir", RTL_LANGS.indexOf(code) > -1 ? "rtl" : "ltr");
  document.documentElement.setAttribute("lang", code);
  document.querySelectorAll("[data-i18n]").forEach(function(el){
    var k = el.getAttribute("data-i18n");
    if(dict[k] !== undefined) el.textContent = dict[k];
  });
  document.querySelectorAll("[data-i18n-html]").forEach(function(el){
    var k = el.getAttribute("data-i18n-html");
    if(dict[k] !== undefined) el.innerHTML = dict[k];
  });
  document.querySelectorAll("[data-i18n-ph]").forEach(function(el){
    var k = el.getAttribute("data-i18n-ph");
    if(dict[k] !== undefined) el.setAttribute("placeholder", dict[k]);
  });
  var names = {en:"English", hi:"हिन्दी", ar:"Arabic", fr:"Français", es:"Español", de:"Deutsch", gu:"ગુજરાતી"};
  var cur = document.getElementById("langCur");
  if(cur) cur.textContent = names[code] || "English";
  var menu = document.getElementById("langMenu");
  if(menu) menu.classList.remove("open");
}

function toggleLangMenu(e){
  if(e) e.stopPropagation();
  var m = document.getElementById("langMenu");
  if(m) m.classList.toggle("open");
}
document.addEventListener("click", function(){
  var m = document.getElementById("langMenu");
  if(m) m.classList.remove("open");
});

(function(){
  var saved = "en";
  try{ saved = localStorage.getItem("ac_lang") || "en"; }catch(e){}
  if(document.readyState === "loading"){
    document.addEventListener("DOMContentLoaded", function(){ applyLang(saved); });
  } else { applyLang(saved); }
})();
